/*
 * A166573  Prime numbers containing the string 13.
 * https://oeis.org/A166573
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 400, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  a(n) = the n-th prime whose decimal representation contains the
 *  substring "13" (OEIS A166573).  The sequence is generated by a
 *  simple sieve of Eratosthenes and a linear scan of the primes.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/*  External types supplied by the build system.  */
extern seq_t a(idx_t n);

/*  ---------- cache for the sequence  ---------- */
static seq_t *cache      = NULL;
static size_t cache_size = 0;      /* number of terms stored       */
static size_t cache_cap  = 0;      /* current capacity             */

/*  ---------- sieve data  ---------- */
static bool *sieve = NULL;        /* true  = prime, false = composite  */
static idx_t sieve_limit = 0;     /* current upper bound of the sieve  */
static idx_t next_check  = 2;     /* next integer to inspect          */

/*  ---------- test for substring "13"  ---------- */
static bool contains13_uint64(uint64_t x)
{
    if (x < 13ULL)
        return false;
    uint64_t prev = x % 10ULL;
    x /= 10ULL;
    while (x) {
        uint64_t d = x % 10ULL;
        if (d == 1ULL && prev == 3ULL)   /* digits "1" followed by "3" */
            return true;
        prev = d;
        x /= 10ULL;
    }
    return false;
}

/*  ---------- build a new sieve up to 'limit'  ---------- */
static void build_sieve(idx_t limit)
{
    /* free old sieve */
    if (sieve)
        free(sieve);

    /* allocate new sieve */
    sieve = (bool *)malloc((size_t)(limit + 1) * sizeof(bool));
    if (!sieve)
        exit(1);   /* out of memory */

    /* initialise as all true */
    for (idx_t i = 0; i <= limit; ++i)
        sieve[i] = true;

    /* 0 and 1 are not prime */
    if (limit >= 0)
        sieve[0] = false;
    if (limit >= 1)
        sieve[1] = false;

    /* Eratosthenes: cross off multiples */
    for (idx_t p = 2; p * p <= limit; ++p) {
        if (sieve[p]) {
            for (idx_t mult = p * p; mult <= limit; mult += p)
                sieve[mult] = false;
        }
    }

    sieve_limit = limit;
}

/*  ---------- main sequence function  ---------- */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;   /* sequence offset is 1 */

    /* return cached value if already computed */
    if (n <= cache_size)
        return cache[n - 1];

    /* expand the cache until we have the nth term */
    while (cache_size < n) {
        /* if we have run out of sieve space, enlarge it */
        if (next_check > sieve_limit) {
            idx_t new_limit = sieve_limit ? (sieve_limit < UINT64_MAX / 2 ? sieve_limit * 2 : sieve_limit)
                                          : 200000ULL;
            if (new_limit < next_check)
                new_limit = next_check;
            build_sieve(new_limit);
        }

        /* scan the sieve from next_check up to sieve_limit */
        for (idx_t p = next_check; p <= sieve_limit; ++p) {
            if (sieve[p] && contains13_uint64((uint64_t)p)) {
                /* enlarge cache if needed */
                if (cache_size == cache_cap) {
                    cache_cap = cache_cap ? cache_cap * 2 : 16;
                    cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                    if (!cache)
                        exit(1);   /* out of memory */
                }
                cache[cache_size++] = (seq_t)p;
                if (cache_size >= n) {
                    next_check = p + 1;
                    break;
                }
            }
        }

        /* if we didn't finish, move to the end of the current sieve
           and let the loop enlarge it again */
        if (cache_size < n)
            next_check = sieve_limit + 1;
    }

    return cache[n - 1];
}
